import Image from "next/image";
import Link from "next/link";
import { MobileNav } from "./MobileNav";
import type { NavCta, NavItem } from "./nav-types";

export type { NavCta, NavItem } from "./nav-types";

export interface AppBarProps {
  /** Primary navigation links, rendered on desktop and inside the mobile menu. */
  navItems?: NavItem[];
  /** Href for the logo/wordmark link. Defaults to the home page. */
  homeHref?: string;
  /**
   * Optional primary call-to-action, shown as a button on desktop and as the
   * last item of the mobile menu. Pass `null` to omit it entirely.
   */
  cta?: NavCta | null;
}

const DEFAULT_NAV_ITEMS: NavItem[] = [
  { label: "홈", href: "/" },
  { label: "에코체크", href: "/search" },
  { label: "지원사업", href: "/programs" },
  { label: "마이페이지", href: "/mypage" },
];

const DEFAULT_CTA: NavCta = {
  label: "건물 에너지 확인하기",
  href: "/search",
};

/**
 * Sticky top-level app bar: brand mark + desktop nav, with an accessible
 * disclosure-style menu for narrow viewports (delegated to `MobileNav`).
 */
export function AppBar({ navItems = DEFAULT_NAV_ITEMS, homeHref = "/", cta = DEFAULT_CTA }: AppBarProps) {
  return (
    <header className="sticky top-0 z-40 border-b border-[var(--border-subtle)] bg-[var(--surface-card)]">
      <div className="eco-container flex h-[var(--app-bar-height)] items-center justify-between gap-[var(--space-4)]">
        <Link
          href={homeHref}
          className="flex shrink-0 items-center gap-[var(--space-2)] rounded-[var(--radius-sm)]"
          aria-label="에코체크 홈으로 이동"
        >
          <Image src="/assets/logo-mark.png" alt="" width={36} height={36} preload className="h-9 w-9" />
          <span className="eco-heading text-[var(--text-strong)]">에코체크</span>
        </Link>

        <nav aria-label="주요 메뉴" className="hidden items-center gap-[var(--space-1)] md:flex">
          {navItems.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              aria-current={item.active ? "page" : undefined}
              className="rounded-[var(--radius-md)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-label-size)] font-medium text-[var(--text-body)] transition-colors duration-[var(--dur-fast)] hover:bg-[var(--surface-sunken)] hover:text-[var(--text-strong)] aria-[current=page]:font-bold aria-[current=page]:text-[var(--text-link)]"
            >
              {item.label}
            </Link>
          ))}
        </nav>

        <div className="hidden shrink-0 md:block">
          {cta ? (
            <Link
              href={cta.href}
              className="inline-flex items-center justify-center rounded-[var(--radius-pill)] bg-[var(--action-primary)] px-[var(--space-5)] py-[var(--space-2)] text-[length:var(--text-label-size)] font-bold text-[var(--text-on-primary)] transition-colors duration-[var(--dur-fast)] hover:bg-[var(--action-primary-hover)] active:bg-[var(--action-primary-press)]"
            >
              {cta.label}
            </Link>
          ) : null}
        </div>

        <MobileNav items={navItems} cta={cta ?? undefined} />
      </div>
    </header>
  );
}
