import { GRADES, type GradeCode } from "../../data/grades";
import { getGradeColorVars } from "./grade-tokens";

export type EnergyGradeBadgeSize = "sm" | "md" | "lg";

export interface EnergyGradeBadgeProps {
  grade: GradeCode;
  size?: EnergyGradeBadgeSize;
  /** Also render the grade's full label (e.g. "5등급") next to the chip. */
  showLabel?: boolean;
  className?: string;
}

const SIZE_CLASSES: Record<EnergyGradeBadgeSize, string> = {
  sm: "h-6 px-[var(--space-2)] text-[length:var(--text-caption-size)]",
  md: "h-8 px-[var(--space-3)] text-[length:var(--text-label-size)]",
  lg: "h-11 px-[var(--space-4)] text-[length:var(--text-subhead-size)]",
};

/** Color-coded pill for a building energy-efficiency grade (`1+++` best … `7` worst). */
export function EnergyGradeBadge({ grade, size = "md", showLabel = false, className }: EnergyGradeBadgeProps) {
  const { color, soft } = getGradeColorVars(grade);
  const definition = GRADES[grade];
  const chipClassName = [
    "inline-flex items-center justify-center rounded-[var(--radius-pill)] font-black tabular-nums",
    SIZE_CLASSES[size],
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <span className="inline-flex items-center gap-[var(--space-2)]">
      <span
        className={chipClassName}
        style={{
          backgroundColor: `var(${soft})`,
          color: `var(${color})`,
          borderColor: `var(${color})`,
          borderWidth: "var(--border-width-strong)",
          borderStyle: "solid",
        }}
      >
        {grade}
        {!showLabel ? <span className="sr-only"> 등급 ({definition.label})</span> : null}
      </span>
      {showLabel ? (
        <span className="text-[length:var(--text-label-size)] font-medium text-[var(--text-body)]">
          {definition.label}
        </span>
      ) : null}
    </span>
  );
}
