import Link from "next/link";
import type { SupportProgram } from "../../data/programs";
import { formatDate, formatManwon } from "../../lib/format";

export interface ProgramCardProps {
  program: SupportProgram;
  /** When given, the whole card links to the program's detail page. */
  href?: string;
  className?: string;
}

/** Card summarizing a government/public building-energy support program. */
export function ProgramCard({ program, href, className }: ProgramCardProps) {
  const deadlineLabel = program.deadline === "상시" ? "상시 모집" : `~${formatDate(program.deadline)} 마감`;

  const cardClassName = [
    "h-full rounded-[var(--radius-lg)] border border-[var(--border-subtle)] bg-[var(--surface-card)] p-[var(--pad-card)] shadow-[var(--shadow-card)] transition-shadow duration-[var(--dur-base)]",
    href ? "group-hover:shadow-[var(--shadow-raised)]" : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  const content = (
    <article className={cardClassName}>
      <div className="flex items-start justify-between gap-[var(--space-3)]">
        <span className="inline-flex items-center rounded-[var(--radius-pill)] bg-[var(--surface-brand-soft)] px-[var(--space-3)] py-[var(--space-1)] text-[length:var(--text-caption-size)] font-bold text-[var(--text-link)]">
          {program.provider}
        </span>
        <span className="shrink-0 text-[length:var(--text-caption-size)] font-medium text-[var(--text-muted)]">
          {deadlineLabel}
        </span>
      </div>
      <h3 className="eco-subhead mt-[var(--space-3)] text-[var(--text-strong)]">{program.name}</h3>
      <p className="mt-[var(--space-2)] text-[length:var(--text-body-size)] leading-[var(--text-body-lh)] text-[var(--text-body)]">
        {program.summary}
      </p>
      {program.maxSupportManwon ? (
        <p className="mt-[var(--space-4)] text-[length:var(--text-label-size)] font-bold text-[var(--status-good)]">
          최대 {formatManwon(program.maxSupportManwon)} 지원
        </p>
      ) : null}
    </article>
  );

  if (href) {
    return (
      <Link href={href} className="group block">
        {content}
      </Link>
    );
  }

  return content;
}
